#include <bits/stdc++.h>
using namespace std;

static int n, t;

struct Room {
    int i, j;
    array<bool, 61> infected;
    array<bool, 61> accessible;
    int scientists, capsules;

    Room() : scientists(0), capsules(0) {
        infected.fill(false);
        accessible.fill(true);
    }

    int get_node_id(int timestamp) const {
        return 2 + i + n * j + (n * n) * timestamp;
    }

    void set_reactor() {
        accessible.fill(false);
    }

    void set_infected(int timestamp = 0) {
        if (accessible[timestamp]) {
            accessible[timestamp] = false;
            infected[timestamp] = true;
        }
    }

    void spread_infection(int timestamp);
};

static array<array<Room, 10>, 10> floorplan;

void Room::spread_infection(int timestamp) {
    if (!infected[timestamp]) return;

    set_infected(timestamp + 1);

    if (i > 0) floorplan[i - 1][j].set_infected(timestamp + 1);
    if (i < n - 1) floorplan[i + 1][j].set_infected(timestamp + 1);
    if (j > 0) floorplan[i][j - 1].set_infected(timestamp + 1);
    if (j < n - 1) floorplan[i][j + 1].set_infected(timestamp + 1);
}

struct Edge {
    int from, to;
    double length;

    Edge(int f, int t, double l) : from(f), to(t), length(l) {}
};

struct Node {
    vector<int> out;
};

struct Graph {
    vector<Node> nodes;
    vector<Edge> edges;

    Graph(int n) {
        nodes.resize(n);
    }

    void add_edge(int from, int to, double length) {
        edges.emplace_back(from, to, length);
        nodes[from].out.push_back((int)edges.size() - 1);
    }

    vector<int> find_augmenting_path(int source, int sink,
                                     const vector<double> &flow,
                                     double *path_cap) {
        vector<double> cap(nodes.size(), 0.0);
        vector<int> pred(nodes.size(), -1);
        priority_queue<pair<double, int>> pq;

        cap[source] = INFINITY;
        pq.push({INFINITY, source});

        while (!pq.empty() && cap[sink] == 0.0) {
            auto cur = pq.top();
            pq.pop();

            double c = cur.first;
            int v = cur.second;

            if (c < cap[v]) continue;

            for (int eidx : nodes[v].out) {
                Edge &e = edges[eidx];
                double rem = e.length - flow[eidx];

                if (rem > 0.0) {
                    double nc = min(c, rem);

                    if (nc > cap[e.to]) {
                        cap[e.to] = nc;
                        pred[e.to] = eidx;
                        pq.push({nc, e.to});
                    }
                }
            }
        }

        *path_cap = cap[sink];

        vector<int> path;
        int eidx = pred[sink];

        while (eidx != -1) {
            path.push_back(eidx);
            eidx = pred[edges[eidx].from];
        }

        return path;
    }

    double max_flow(int source, int sink) {
        Graph residual(nodes.size());

        for (const Edge &e : edges) {
            residual.add_edge(e.from, e.to, e.length);
            residual.add_edge(e.to, e.from, 0.0);
        }

        vector<double> flow(residual.edges.size(), 0.0);
        double path_cap;

        vector<int> path =
            residual.find_augmenting_path(source, sink, flow, &path_cap);

        while (path_cap > 0.0) {
            for (int eidx : path) {
                int rev = eidx ^ 1;
                flow[eidx] += path_cap;
                flow[rev] -= path_cap;
            }

            path = residual.find_augmenting_path(source, sink, flow, &path_cap);
        }

        double total = 0.0;

        for (int eidx : residual.nodes[source].out) {
            total += flow[eidx];
        }

        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);

    cin >> n >> t;

    for (int i = 0; i < n; i++) {
        string line;
        cin >> line;

        for (int j = 0; j < n; j++) {
            floorplan[i][j].i = i;
            floorplan[i][j].j = j;

            if (line[j] == 'Y') floorplan[i][j].set_reactor();
            else if (line[j] == 'Z') floorplan[i][j].set_infected();
            else floorplan[i][j].scientists = line[j] - '0';
        }
    }

    for (int i = 0; i < n; i++) {
        string line;
        cin >> line;

        for (int j = 0; j < n; j++) {
            if (line[j] != 'Y' && line[j] != 'Z') {
                floorplan[i][j].capsules = line[j] - '0';
            }
        }
    }

    for (int c = 0; c <= t; c++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (c < t) floorplan[i][j].spread_infection(c);
            }
        }
    }

    Graph g(n * n * (t + 1) + 2);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            const Room &room = floorplan[i][j];

            if (room.scientists > 0) {
                g.add_edge(0, room.get_node_id(0), room.scientists);
            }

            if (room.capsules > 0) {
                g.add_edge(room.get_node_id(t), 1, room.capsules);
            }

            for (int c = 0; c < t; c++) {
                if (room.capsules > 0) {
                    g.add_edge(room.get_node_id(c), room.get_node_id(t), 1000);
                }

                if (room.accessible[c]) {
                    if (i > 0 && floorplan[i - 1][j].accessible[c]) {
                        g.add_edge(room.get_node_id(c),
                                   floorplan[i - 1][j].get_node_id(c + 1), 1000);
                    }

                    if (i < n - 1 && floorplan[i + 1][j].accessible[c]) {
                        g.add_edge(room.get_node_id(c),
                                   floorplan[i + 1][j].get_node_id(c + 1), 1000);
                    }

                    if (j > 0 && floorplan[i][j - 1].accessible[c]) {
                        g.add_edge(room.get_node_id(c),
                                   floorplan[i][j - 1].get_node_id(c + 1), 1000);
                    }

                    if (j < n - 1 && floorplan[i][j + 1].accessible[c]) {
                        g.add_edge(room.get_node_id(c),
                                   floorplan[i][j + 1].get_node_id(c + 1), 1000);
                    }
                }
            }
        }
    }

    cout << int(g.max_flow(0, 1)) << '\n';

    return 0;
}
